package com.crh.logon.webservices.clients.beans.goodsmovement;

import java.io.Serializable;
import java.util.List;
import com.crh.logon.webservices.clients.AbstractSAPDocumentDTO;

/**
 * @author AdNovum Informatik AG
 *  
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Please use business terms for the fields in this object, usually the wsdl's
 * documentation for a field is OK. Just don't use the SAP names like VKORG, 
 * VTWEG etc.
 */
public class GoodsMovementDTO extends AbstractSAPDocumentDTO implements Serializable {

	/**
	 * WS field to SAP: ShipmentDocumentCreation / goods_movement /
	 * goods_movements_mobile_data_entry_header / BLDAT
	 */
	private String documentDateInDocument;

	/**
	 * WS field to SAP: ShipmentDocumentCreation / goods_movement /
	 * goods_movements_mobile_data_entry_header / BUDAT
	 */
	private String postingDateInDocument;

	/**
	 * WS field to SAP: ShipmentDocumentCreation / goods_movement /
	 * goods_movements_mobile_data_entry_header / TCODE
	 */
	private String currentTransactionCode;
	public static final String CURRENT_TRANSACTION_CODE_DEFAULT = "MB1B";

	/**
	 * WS field to SAP: ShipmentDocumentCreation / goods_movement /
	 * goods_movements_mobile_data_entry_header / USNAM
	 */
	private String userName;
	public static final String USER_NAME_DEFAULT = "LOGON";

	/**
	 * WS field to SAP: ShipmentDocumentCreation / goods_movement /
	 * goods_movements_mobile_data_entry_header / XBLNR_LONG
	 */
	private String referenceDocumentNumber;

	/**
	 * WS field to SAP: ShipmentDocumentCreation / goods_movement /
	 * goods_movements_mobile_data_entry_header / only one item included here.
	 */
	private List<GoodsMovementItemDTO> goodsMovementItemList;

	public String getDocumentDateInDocument() {
		return documentDateInDocument;
	}

	public void setDocumentDateInDocument(String documentDateInDocument) {
		this.documentDateInDocument = documentDateInDocument;
	}

	public String getPostingDateInDocument() {
		return postingDateInDocument;
	}

	public void setPostingDateInDocument(String postingDateInDocument) {
		this.postingDateInDocument = postingDateInDocument;
	}

	public String getCurrentTransactionCode() {
		return currentTransactionCode;
	}

	public void setCurrentTransactionCode(String currentTransactionCode) {
		this.currentTransactionCode = currentTransactionCode;
	}

	public String getUserName() {
		return userName;
	}

	public void setUserName(String userName) {
		this.userName = userName;
	}

	public String getReferenceDocumentNumber() {
		return referenceDocumentNumber;
	}

	public void setReferenceDocumentNumber(String referenceDocumentNumber) {
		this.referenceDocumentNumber = referenceDocumentNumber;
	}

	public List<GoodsMovementItemDTO> getGoodsMovementItemList() {
		return goodsMovementItemList;
	}

	public void setGoodsMovementItemList(List<GoodsMovementItemDTO> goodsMovementItemList) {
		this.goodsMovementItemList = goodsMovementItemList;
	}

}
